-- chair-step: inverse of read_lane_v2_b3_05_workspace_projects — un-enrolls workspace.projects from read-lane v2 and regenerates it back to the set-form read lane.
delete from iam.read_lane_v2_rollout where token = (select token from platform.entity_types where schema_name = 'workspace' and table_name = 'projects' and is_active);
select iam.apply_rls('workspace', 'projects', (select token from platform.entity_types where schema_name = 'workspace' and table_name = 'projects' and is_active), (select rls_variant from platform.entity_types where schema_name = 'workspace' and table_name = 'projects' and is_active));
